"""Canonical identities for claims and their generated bytes."""

from __future__ import annotations

import hashlib
import json
import os

from . import core, recipe as recipe_module


def _canonical(value: object) -> bytes:
    """Encode the identity format's default-spaced, sorted ASCII JSON."""
    try:
        return json.dumps(value, sort_keys=True).encode("utf-8")
    except (TypeError, ValueError) as exc:
        raise core.ClaimError(f"recipe has no canonical JSON form: {exc}") from exc


def _claim_format(recipe: dict) -> int:
    return recipe.get("claim", {}).get("format", 1)


def _preimage_recipe(recipe: dict) -> dict:
    """Return the parsed recipe as it appears in the root preimage."""
    version = _claim_format(recipe)
    if version < 3:
        return recipe

    preimage = dict(recipe)
    if "step" in recipe:
        steps = []
        for step in recipe["step"]:
            copied = dict(step)
            copied.pop("guidance", None)
            copied.pop("request", None)
            steps.append(copied)
        if version >= 4:
            steps.sort(key=_canonical)
        preimage["step"] = steps
    return preimage


def _parts(recipe: dict, directory: str | os.PathLike[str]) -> dict[str, str]:
    """Collect the canonical recipe and every declared pinned file digest."""
    parts = {"digest": core.DIGEST,
             "recipe": _canonical(_preimage_recipe(recipe)).decode("utf-8")}
    for name in recipe_module._inputs(recipe, directory):
        parts["input:" + name] = core._hash_file(core._safe(directory, name))
    for step in recipe_module._steps(recipe):
        kind = step["kind"]
        klass = step.get("class", "generated" if kind == "produce" else "pinned")
        if klass not in ("generated", "free"):
            name = step["output"]
            parts["pinned:" + name] = core._hash_file(core._safe(directory, name))
    return parts


def root(recipe: dict, directory: str | os.PathLike[str]) -> str:
    """Hash a claim's criteria and pinned bytes."""
    return hashlib.sha256(_canonical(_parts(recipe, directory))).hexdigest()


def build_digest(directory: str | os.PathLike[str]) -> str:
    """Hash the available, locally generated output bytes."""
    parsed = recipe_module.load_recipe(directory)
    generated = []
    for name in recipe_module.generated_outputs(parsed):
        path = core._safe(directory, name)
        if os.path.lexists(path):
            generated.append([name, core._hash_file(path)])
    generated.sort()
    return hashlib.sha256(_canonical(generated)).hexdigest()
